def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []  # stack of reversible operations
    rejected = []

    def is_valid_amount(s: str) -> bool:
        return s.isdigit() and len(s) > 0

    def parse_amount(s: str) -> int:
        return int(s)

    for idx, op in enumerate(ops):
        tokens = op.split()
        verb = tokens[0] if tokens else ""

        if verb == "open":
            if len(tokens) != 3:
                rejected.append(idx)
                continue
            a, n_str = tokens[1], tokens[2]
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = parse_amount(n_str)
            if n < 0:
                rejected.append(idx)
                continue
            if a in accounts:
                rejected.append(idx)
                continue
            accounts[a] = (n, False)
            history.append(("open", a))

        elif verb == "deposit":
            if len(tokens) != 3:
                rejected.append(idx)
                continue
            a, n_str = tokens[1], tokens[2]
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = parse_amount(n_str)
            if n <= 0:
                rejected.append(idx)
                continue
            if a not in accounts:
                rejected.append(idx)
                continue
            old_balance, frozen = accounts[a]
            accounts[a] = (old_balance + n, frozen)
            history.append(("deposit", a, n))

        elif verb == "withdraw":
            if len(tokens) != 3:
                rejected.append(idx)
                continue
            a, n_str = tokens[1], tokens[2]
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = parse_amount(n_str)
            if n <= 0:
                rejected.append(idx)
                continue
            if a not in accounts:
                rejected.append(idx)
                continue
            old_balance, frozen = accounts[a]
            if frozen:
                rejected.append(idx)
                continue
            if old_balance < n:
                rejected.append(idx)
                continue
            accounts[a] = (old_balance - n, frozen)
            history.append(("withdraw", a, n))

        elif verb == "transfer":
            if len(tokens) != 4:
                rejected.append(idx)
                continue
            a, b, n_str = tokens[1], tokens[2], tokens[3]
            if not is_valid_amount(n_str):
                rejected.append(idx)
                continue
            n = parse_amount(n_str)
            if n <= 0:
                rejected.append(idx)
                continue
            if a == b:
                rejected.append(idx)
                continue
            if a not in accounts or b not in accounts:
                rejected.append(idx)
                continue
            old_balance_a, frozen_a = accounts[a]
            old_balance_b, frozen_b = accounts[b]
            if frozen_a:
                rejected.append(idx)
                continue
            if old_balance_a < n:
                rejected.append(idx)
                continue
            accounts[a] = (old_balance_a - n, frozen_a)
            accounts[b] = (old_balance_b + n, frozen_b)
            history.append(("transfer", a, b, n))

        elif verb == "freeze":
            if len(tokens) != 2:
                rejected.append(idx)
                continue
            a = tokens[1]
            if a not in accounts:
                rejected.append(idx)
                continue
            old_balance, frozen = accounts[a]
            if frozen:
                rejected.append(idx)
                continue
            accounts[a] = (old_balance, True)
            history.append(("freeze", a))

        elif verb == "unfreeze":
            if len(tokens) != 2:
                rejected.append(idx)
                continue
            a = tokens[1]
            if a not in accounts:
                rejected.append(idx)
                continue
            old_balance, frozen = accounts[a]
            if not frozen:
                rejected.append(idx)
                continue
            accounts[a] = (old_balance, False)
            history.append(("unfreeze", a))

        elif verb == "undo":
            if len(tokens) != 1:
                rejected.append(idx)
                continue
            if not history:
                rejected.append(idx)
                continue
            op_type = history.pop()
            if op_type[0] == "open":
                a = op_type[1]
                del accounts[a]
            elif op_type[0] == "deposit":
                a, n = op_type[1], op_type[2]
                old_balance, frozen = accounts[a]
                accounts[a] = (old_balance - n, frozen)
            elif op_type[0] == "withdraw":
                a, n = op_type[1], op_type[2]
                old_balance, frozen = accounts[a]
                accounts[a] = (old_balance + n, frozen)
            elif op_type[0] == "transfer":
                a, b, n = op_type[1], op_type[2], op_type[3]
                old_balance_a, frozen_a = accounts[a]
                old_balance_b, frozen_b = accounts[b]
                accounts[a] = (old_balance_a + n, frozen_a)
                accounts[b] = (old_balance_b - n, frozen_b)
            elif op_type[0] == "freeze":
                a = op_type[1]
                old_balance, frozen = accounts[a]
                accounts[a] = (old_balance, False)
            elif op_type[0] == "unfreeze":
                a = op_type[1]
                old_balance, frozen = accounts[a]
                accounts[a] = (old_balance, True)

        else:
            rejected.append(idx)

    balances = {name: state[0] for name, state in accounts.items()}
    return (balances, rejected)
